-- 单元测试用 H2 建表，字段与 V101__mdm_cross_ref.sql 的 MySQL 定义一一对应；
-- H2 不支持 ON UPDATE CURRENT_TIMESTAMP，update_time 仅保留默认值，与既有 Starter 的测试 DDL 处理一致。
CREATE TABLE IF NOT EXISTS "mdm_cross_ref" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "source_system" varchar(32) NOT NULL,
    "source_entity" varchar(32) NOT NULL,
    "source_id" varchar(64) NOT NULL,
    "target_system" varchar(32) NOT NULL,
    "target_entity" varchar(32) NOT NULL,
    "target_id" varchar(64) NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'VALID',
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE KEY "uk_cross_ref" ("tenant_id", "source_system", "source_entity", "source_id", "target_system", "target_entity")
);

CREATE INDEX IF NOT EXISTS "idx_tenant_source" ON "mdm_cross_ref" ("tenant_id", "source_system", "source_entity", "source_id");